// Common事实序是婚议、收养关系和死亡的共同时间轴；不使用当前婚姻/亲属索引回填旧决定。
#include "family_marriage.hpp"
#include <charconv>
#include <map>
#include <tuple>
namespace hanmo::resident {namespace {
// 本域事实必须沿原实例号分配；自由文本ID不得装成已办理来源。
bool fact_id(const CommonStore& c,const StableId& id){const StableId prefix="family_marriage:";if(id.rfind(prefix,0)!=0)return false;const auto text=id.substr(prefix.size());Integer n=0;auto result=std::from_chars(text.data(),text.data()+text.size(),n);return result.ec==std::errc{}&&result.ptr==text.data()+text.size()&&n>0&&n<c.state().next_instance_id&&text==std::to_string(n);}
// 处境纯读必须以本次候选和同一边界返回；缺实现不当作无占用。
Status availability(const MarriageAccess& access,const StableId& actor,Integer tick,const StableId& boundary){return access.personally_available?access.personally_available(actor,tick,boundary):common_failure("MarriageAvailabilityHistoryRequired",actor);}
// 原历史玩家只证明这一决定由当时受控本人作出，不授代签另一个人的权限。
Status player(const MarriageAccess& access,const StableId& actor,Integer tick,const StableId& boundary){if(!access.player_before)return common_failure("MarriageHistoricalPlayerRequired");auto read=access.player_before(tick,boundary);if(!read.ok)return {false,{},read.error};return read.value==actor?common_success():common_failure("MarriagePersonalDecisionRequired",actor);}
// 血亲未知保持未知；此处只拒已证实收养直系与同一收养父母的兄弟姐妹。
bool known_close(const std::map<StableId,StableId>& parents,const StableId& first,const StableId& second){if(first==second)return true;auto ancestors=[&](StableId actor){std::set<StableId> out;while(parents.count(actor)){actor=parents.at(actor);if(!out.insert(actor).second)break;}return out;};const auto a=ancestors(first),b=ancestors(second);if(a.count(second)||b.count(first))return true;auto x=parents.find(first),y=parents.find(second);return x!=parents.end()&&y!=parents.end()&&x->second==y->second;}
// 双向索引只能同时撤去，遗属仍保留原婚姻事实和外部照护/产权责任。
void close_bond(MarriageTimeline& timeline,const StableId& actor){const auto* found=timeline.active_by_actor.find(actor);if(!found)return;const auto bond=*found;timeline.active_by_actor.erase(bond.first_actor_id);timeline.active_by_actor.erase(bond.second_actor_id);}
// 所有命令在原本人仍在世时办理，死者不能事后补签拒绝、接受或撤回。
Status current_person(const CommonStore& c,const StableId& actor){const auto* person=c.actor(actor);if(actor!=c.state().metadata.player_actor_id||!person||!person->alive||!person->available||!person->action_id.empty())return common_failure("MarriageLivingDecisionMakerRequired",actor);return common_success();}
// 本账和Common保存点共同提交；晚期历史来源失败不会留下单方关系或占用实例号。
template<class Insert>Outcome<StableId> publish(CommonStore& c,FamilyMarriageState& state,const StableId& kind,Insert insert,const std::function<Status(const FamilyMarriageState&)>& validate){auto mark=c.begin_savepoint();if(!mark.ok)return {false,{},mark.error};auto next=state;auto abort=[&](const Status& failure)->Outcome<StableId>{auto rolled=c.rollback_savepoint(mark.value);return {false,{},rolled.ok?failure.error:rolled.error};};auto id=c.next_id("family_marriage");if(!id.ok)return abort({false,{},id.error});auto valid=insert(next,id.value);if(!valid.ok)return abort(valid);valid=c.append_fact({id.value,kind,"family_marriage"});if(!valid.ok)return abort(valid);valid=validate(next);if(!valid.ok)return abort(valid);valid=c.commit_savepoint(mark.value);if(!valid.ok)return {false,{},valid.error};state=std::move(next);return {true,id.value,{}};}
}
Outcome<MarriageTimeline> validate_family_marriage(const CommonStore& c,const FamilyState& family,const FamilyDeathState& deaths,const InteractionCatalog& interaction,const MarriageSourceCatalog& catalog,const FamilyMarriageState& state,const MarriageAccess& access){
    auto fail=[](const StableId& code,const StableId& id=StableId{})->Outcome<MarriageTimeline>{return {false,{},common_failure(code,id).error};};
    if(!interaction.common)return fail("MarriageCommonCatalogRequired");auto valid=validate_marriage_source_catalog(catalog,*interaction.common,interaction);if(!valid.ok)return {false,{},valid.error};if(!catalog.enabled){if(!state.proposals.empty()||!state.replies.empty()||!state.dissolutions.empty())return fail("MarriageProfileRequired");for(const auto& row:c.state().facts.rows())if(row.second.domain=="family_marriage")return fail("MarriageProfileRequired");return {true,{}, {}};}
    MarriageTimeline out;out.known_kinship=access.known_kinship;for(const auto& row:catalog.origins.rows())if(row.second.status=="married"){const auto& other=*row.second.spouse_actor_id;if(access.known_kinship){valid=access.known_kinship({},row.first,other);if(!valid.ok)return {false,{},valid.error};}MarriageBond bond{std::min(row.first,other),std::min(row.first,other),std::max(row.first,other),true};out.active_by_actor.insert(row.first,bond);}
    std::map<StableId,std::vector<StableId>> deaths_at;for(const auto& row:deaths.deaths.rows())deaths_at[row.second.cause_fact_id].push_back(row.second.actor_id);std::set<StableId> dead,seen,offered_statements;std::map<StableId,StableId> parents;Integer latest_tick=0,latest_revision=0;
    auto alive=[&](const StableId& actor){const auto* person=c.actor(actor);if(!person||dead.count(actor))return false;if(person->alive)return true;return family_death_for_actor(deaths,actor)!=nullptr;};
    auto source=[&](const MarriageStatementSource& s,const StableId& boundary)->Status{auto r=validate_marriage_statement_source(c.state(),*interaction.common,interaction,catalog,s);if(!r.ok)return r;if(!alive(s.speaker_actor_id)||!alive(s.listener_actor_id))return common_failure("MarriageStatementAfterDeath");r=player(access,s.listener_actor_id,s.tick,boundary);if(!r.ok)return r;for(const auto* actor:{&s.speaker_actor_id,&s.listener_actor_id}){r=availability(access,*actor,s.tick,boundary);if(!r.ok)return r;}return common_success();};
    auto single=[&](const StableId& actor)->Status{const auto* origin=catalog.origins.find(actor);if(!origin||origin->status=="unknown")return common_failure("MarriageOriginalStatusUnknown",actor);if(out.death_knowledge_pending.count(actor))return common_failure("MarriageCurrentStatusUnconfirmed",actor);return out.active_by_actor.find(actor)?common_failure("MarriageExistingBond",actor):common_success();};
    for(const auto& row:c.state().facts.rows()){
        if(auto dying=deaths_at.find(row.first);dying!=deaths_at.end())for(const auto& actor:dying->second){dead.insert(actor);if(const auto* bond=out.active_by_actor.find(actor))out.death_knowledge_pending.insert(bond->first_actor_id==actor?bond->second_actor_id:bond->first_actor_id);close_bond(out,actor);}
        if(const auto* fact=family.facts.find(row.first)){if(const auto* adult=std::get_if<AdultAdoptionFact>(fact)){auto prior=out;prior.adoptive_parents=parents;valid=validate_marriage_adoption_boundary(prior,adult->agreement.adopter_actor_id,adult->agreement.adoptee_actor_id);if(!valid.ok)return {false,{},valid.error};parents[adult->agreement.adoptee_actor_id]=adult->agreement.adopter_actor_id;}if(const auto* creation=std::get_if<IdentityCreationFact>(fact)){const auto* origin=family.facts.find(creation->source);const auto* adoption=origin?std::get_if<AdoptionFact>(origin):nullptr;if(adoption&&adoption->success&&adoption->child_actor_id==creation->actor_id)parents[creation->actor_id]=adoption->guardian_actor_id;}}
        if(row.second.domain!="family_marriage"){if(state.proposals.find(row.first)||state.replies.find(row.first)||state.dissolutions.find(row.first))return fail("MarriageFactDomainMismatch",row.first);continue;}
        if(!fact_id(c,row.first)||row.second.id!=row.first)return fail("InvalidMarriageFactId",row.first);const auto* proposal=state.proposals.find(row.first);const auto* reply=state.replies.find(row.first);const auto* dissolution=state.dissolutions.find(row.first);if(Integer(bool(proposal))+Integer(bool(reply))+Integer(bool(dissolution))!=1)return fail("MarriageFactPayloadMismatch",row.first);seen.insert(row.first);const Integer event_tick=proposal?proposal->source.tick:reply?reply->tick:dissolution->source.tick,event_revision=proposal?proposal->source.revision:reply?reply->revision:dissolution->source.revision;if(event_tick<latest_tick||event_revision<latest_revision)return fail("MarriageFactTimeReversed",row.first);latest_tick=event_tick;latest_revision=event_revision;
        if(proposal){if(proposal->kind!="family_marriage_proposed"||row.second.kind!=proposal->kind||proposal->source.intent!="offer_marriage"||!offered_statements.insert(proposal->source.statement_id).second)return fail("InvalidMarriageProposal",row.first);valid=source(proposal->source,row.first);if(!valid.ok)return {false,{},valid.error};continue;}
        if(reply){if(reply->kind!="family_marriage_replied"||row.second.kind!=reply->kind||reply->tick<0||reply->tick>c.tick()||reply->revision<0||reply->revision>c.state().identity.revision||!seen.count(reply->proposal_id)||!out.replied_proposals.insert(reply->proposal_id).second)return fail("InvalidMarriageReply",row.first);const auto* original=state.proposals.find(reply->proposal_id);if(!original||reply->tick<original->source.tick||!alive(reply->actor_id))return fail("MarriageReplySourceMismatch",row.first);const auto& offer=original->source;const bool accepted=reply->decision=="accepted",refused=reply->decision=="refused",withdrawn=reply->decision=="withdrawn";if((!accepted&&!refused&&!withdrawn)||reply->actor_id!=(withdrawn?offer.speaker_actor_id:offer.listener_actor_id)||bool(reply->confirmation)!=accepted)return fail("MarriageReplyAuthorityMismatch",row.first);valid=player(access,reply->actor_id,reply->tick,row.first);if(!valid.ok)return {false,{},valid.error};if(!accepted)continue;const auto& consent=*reply->confirmation;if(consent.statement_id!=offer.statement_id||consent.intent!="offer_marriage"||consent.tick!=reply->tick||consent.revision!=reply->revision)return fail("MarriageAcceptanceSourceMismatch",row.first);valid=source(consent,row.first);if(!valid.ok)return {false,{},valid.error};for(const auto* actor:{&consent.speaker_actor_id,&consent.listener_actor_id}){valid=single(*actor);if(!valid.ok)return {false,{},valid.error};}if(known_close(parents,consent.speaker_actor_id,consent.listener_actor_id))return fail("MarriageKnownCloseRelation",row.first);if(access.known_kinship){valid=access.known_kinship(parents,consent.speaker_actor_id,consent.listener_actor_id);if(!valid.ok)return {false,{},valid.error};}MarriageBond bond{row.first,consent.speaker_actor_id,consent.listener_actor_id,false};out.active_by_actor.insert(bond.first_actor_id,bond);out.active_by_actor.insert(bond.second_actor_id,bond);continue;}
        if(dissolution->kind!="family_marriage_dissolved"||row.second.kind!=dissolution->kind||dissolution->source.intent!="accept_dissolution")return fail("InvalidMarriageDissolution",row.first);valid=source(dissolution->source,row.first);if(!valid.ok)return {false,{},valid.error};const auto* bond=out.active_by_actor.find(dissolution->source.listener_actor_id);if(!bond||bond->authored_origin||bond->id!=dissolution->marriage_id||!((bond->first_actor_id==dissolution->source.listener_actor_id&&bond->second_actor_id==dissolution->source.speaker_actor_id)||(bond->second_actor_id==dissolution->source.listener_actor_id&&bond->first_actor_id==dissolution->source.speaker_actor_id)))return fail("MarriageDissolutionBondMismatch",row.first);close_bond(out,dissolution->source.listener_actor_id);
    }
    if(seen.size()!=state.proposals.size()+state.replies.size()+state.dissolutions.size())return fail("MarriageOrphanPayload");out.adoptive_parents=std::move(parents);return {true,std::move(out),{}};
}
// 不向未获知死讯者解释全局死亡真值，仅阻止在本人处境未证时办理新的婚姻。
Status validate_marriage_current_pair(const MarriageSourceCatalog& catalog,const MarriageTimeline& state,const StableId& first,const StableId& second){for(const auto* actor:{&first,&second}){const auto* origin=catalog.origins.find(*actor);if(!origin||origin->status=="unknown")return common_failure("MarriageOriginalStatusUnknown",*actor);if(state.death_knowledge_pending.count(*actor))return common_failure("MarriageCurrentStatusUnconfirmed",*actor);if(state.active_by_actor.find(*actor))return common_failure("MarriageExistingBond",*actor);}if(known_close(state.adoptive_parents,first,second))return common_failure("MarriageKnownCloseRelation");return state.known_kinship?state.known_kinship(state.adoptive_parents,first,second):common_success();}
// 当前预检和原事实重放共用同一冲突规则，不能先形成婚姻再通过收养改成直系。
Status validate_marriage_adoption_boundary(const MarriageTimeline& state,const StableId& adopter,const StableId& adoptee){auto parents=state.adoptive_parents;parents[adoptee]=adopter;for(const auto& row:state.active_by_actor.rows()){const auto& bond=row.second;if(known_close(parents,bond.first_actor_id,bond.second_actor_id))return common_failure("MarriageKinshipConflictsWithExistingBond",adoptee);if(state.known_kinship){auto valid=state.known_kinship(parents,bond.first_actor_id,bond.second_actor_id);if(!valid.ok)return valid;}}return common_success();}
Outcome<StableId> receive_marriage_proposal(CommonStore& c,const FamilyState& family,const FamilyDeathState& deaths,const InteractionState& meeting,const InteractionCatalog& interaction,const InteractionAccess& current,const MarriageSourceCatalog& catalog,FamilyMarriageState& state,const MarriageAccess& access,const MarriageStatementQuote& quote){auto checked=current_person(c,quote.statement.listener_actor_id);if(!checked.ok)return {false,{},checked.error};checked=revalidate_marriage_statement(c,meeting,interaction,current,catalog,quote);if(!checked.ok)return {false,{},checked.error};if(quote.statement.intent!="offer_marriage")return {false,{},common_failure("MarriageOfferRequired").error};auto validate=[&](const FamilyMarriageState& candidate)->Status{auto r=validate_family_marriage(c,family,deaths,interaction,catalog,candidate,access);return r.ok?common_success():Status{false,{},r.error};};checked=validate(state);if(!checked.ok)return {false,{},checked.error};for(const auto& row:state.proposals.rows())if(row.second.source.statement_id==quote.statement.statement_id)return {true,row.first,{}};return publish(c,state,"family_marriage_proposed",[&](FamilyMarriageState& next,const StableId& id){MarriageProposal p;p.source=quote.statement;return next.proposals.insert(id,std::move(p))?common_success():common_failure("DuplicateMarriageProposal");},validate);}
Outcome<StableId> reply_marriage_proposal(CommonStore& c,const FamilyState& family,const FamilyDeathState& deaths,const InteractionState& meeting,const InteractionCatalog& interaction,const InteractionAccess& current,const MarriageSourceCatalog& catalog,FamilyMarriageState& state,const MarriageAccess& access,const StableId& proposal,const StableId& decision,const std::optional<MarriageStatementQuote>& confirmation){const auto actor=c.state().metadata.player_actor_id;auto checked=current_person(c,actor);if(!checked.ok)return {false,{},checked.error};if(confirmation){checked=revalidate_marriage_statement(c,meeting,interaction,current,catalog,*confirmation);if(!checked.ok)return {false,{},checked.error};}auto validate=[&](const FamilyMarriageState& candidate)->Status{auto r=validate_family_marriage(c,family,deaths,interaction,catalog,candidate,access);return r.ok?common_success():Status{false,{},r.error};};checked=validate(state);if(!checked.ok)return {false,{},checked.error};return publish(c,state,"family_marriage_replied",[&](FamilyMarriageState& next,const StableId& id){MarriageReply reply;reply.proposal_id=proposal;reply.actor_id=actor;reply.decision=decision;reply.tick=c.tick();reply.revision=c.state().identity.revision;if(confirmation)reply.confirmation=confirmation->statement;return next.replies.insert(id,std::move(reply))?common_success():common_failure("DuplicateMarriageReply");},validate);}
Outcome<StableId> dissolve_personal_marriage(CommonStore& c,const FamilyState& family,const FamilyDeathState& deaths,const InteractionState& meeting,const InteractionCatalog& interaction,const InteractionAccess& current,const MarriageSourceCatalog& catalog,FamilyMarriageState& state,const MarriageAccess& access,const StableId& marriage,const MarriageStatementQuote& quote){auto checked=current_person(c,quote.statement.listener_actor_id);if(!checked.ok)return {false,{},checked.error};checked=revalidate_marriage_statement(c,meeting,interaction,current,catalog,quote);if(!checked.ok)return {false,{},checked.error};auto validate=[&](const FamilyMarriageState& candidate)->Status{auto r=validate_family_marriage(c,family,deaths,interaction,catalog,candidate,access);return r.ok?common_success():Status{false,{},r.error};};checked=validate(state);if(!checked.ok)return {false,{},checked.error};return publish(c,state,"family_marriage_dissolved",[&](FamilyMarriageState& next,const StableId& id){MarriageDissolution d;d.marriage_id=marriage;d.source=quote.statement;return next.dissolutions.insert(id,std::move(d))?common_success():common_failure("DuplicateMarriageDissolution");},validate);}
}
